import React, { useState } from 'react';
import MicRecorder from './components/MicRecorder';
import TranscriptDisplay from './components/TranscriptDisplay';
import axios from 'axios';

function App() {
  const [messages, setMessages] = useState([]); 

  const speak = (text) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    speechSynthesis.speak(utterance);
  };

  const handleTranscript = async (userInput) => {
    const updatedMessages = [...messages, { role: 'user', content: userInput }];
    const last3 = updatedMessages.slice(-3); 

    try {
      const res = await axios.post(`${process.env.REACT_APP_API_BASE_URL}/chat`, {
        history: last3
      });

      const aiText = res.data.response;
      const updatedWithAI = [...updatedMessages, { role: 'assistant', content: aiText }];
      setMessages(updatedWithAI);
      speak(aiText);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={{ padding: '2em', fontFamily: 'sans-serif' }}>
      <h1>🧠 Voice AI with Memory</h1>
      <MicRecorder onTranscript={handleTranscript} />
      <TranscriptDisplay messages={messages} />
    </div>
  );
}

export default App;
